class Solution {
public:
    long long maximumValueSum(vector<vector<int>>& board) {
        int m = board.size();
        int n = board[0].size();
        vector<vector<pair<int, int>>> row_top3(m);
        for (int r = 0; r < m; ++r) {
            vector<pair<int, int>> row;
            for (int c = 0; c < n; ++c) {
                row.push_back({board[r][c], c});
            }
            sort(row.rbegin(), row.rend());
            row.resize(3);
            row_top3[r] = row;
        }

        auto merge_top3 = [](const vector<pair<int, int>>& a, const vector<pair<int, int>>& b) {
            vector<pair<int, int>> combined = a;
            combined.insert(combined.end(), b.begin(), b.end());
            sort(combined.rbegin(), combined.rend());
            vector<pair<int, int>> res;
            unordered_set<int> seen;
            for (const auto& p : combined) {
                if (!seen.count(p.second)) {
                    seen.insert(p.second);
                    res.push_back(p);
                    if (res.size() == 3) break;
                }
            }
            return res;
        };

        vector<vector<pair<int, int>>> pref(m);
        pref[0] = row_top3[0];
        for (int r = 1; r < m; ++r) {
            pref[r] = merge_top3(pref[r - 1], row_top3[r]);
        }

        vector<vector<pair<int, int>>> suff(m);
        suff[m - 1] = row_top3[m - 1];
        for (int r = m - 2; r >= 0; --r) {
            suff[r] = merge_top3(suff[r + 1], row_top3[r]);
        }

        long long max_sum = -1e18;
        for (int r = 1; r < m - 1; ++r) {
            for (const auto& [v2, c2] : row_top3[r]) {
                for (const auto& [v1, c1] : pref[r - 1]) {
                    if (c1 == c2) continue;
                    for (const auto& [v3, c3] : suff[r + 1]) {
                        if (c3 == c1 || c3 == c2) continue;
                        max_sum = max(max_sum, 1LL * v1 + v2 + v3);
                    }
                }
            }
        }
        return max_sum;
    }
};

class Solution {
    public long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        int[][][] rowTop3 = new int[m][3][2];
        for (int r = 0; r < m; ++r) {
            List<int[]> row = new ArrayList<>();
            for (int c = 0; c < n; ++c) {
                row.add(new int[]{board[r][c], c});
            }
            row.sort((a, b) -> Integer.compare(b[0], a[0]));
            for (int i = 0; i < 3; ++i) {
                rowTop3[r][i] = row.get(i);
            }
        }

        int[][][] pref = new int[m][3][2];
        pref[0] = rowTop3[0];
        for (int r = 1; r < m; ++r) {
            pref[r] = mergeTop3(pref[r - 1], rowTop3[r]);
        }

        int[][][] suff = new int[m][3][2];
        suff[m - 1] = rowTop3[m - 1];
        for (int r = m - 2; r >= 0; --r) {
            suff[r] = mergeTop3(suff[r + 1], rowTop3[r]);
        }

        long maxSum = Long.MIN_VALUE;
        for (int r = 1; r < m - 1; ++r) {
            for (int[] p2 : rowTop3[r]) {
                for (int[] p1 : pref[r - 1]) {
                    if (p1[1] == p2[1]) continue;
                    for (int[] p3 : suff[r + 1]) {
                        if (p3[1] == p1[1] || p3[1] == p2[1]) continue;
                        maxSum = Math.max(maxSum, (long) p1[0] + p2[0] + p3[0]);
                    }
                }
            }
        }
        return maxSum;
    }

    private int[][] mergeTop3(int[][] a, int[][] b) {
        List<int[]> combined = new ArrayList<>();
        for (int[] x : a) combined.add(x);
        for (int[] x : b) combined.add(x);
        combined.sort((x, y) -> Integer.compare(y[0], x[0]));
        int[][] res = new int[3][2];
        Set<Integer> seen = new HashSet<>();
        int idx = 0;
        for (int[] p : combined) {
            if (!seen.contains(p[1])) {
                seen.add(p[1]);
                res[idx++] = p;
                if (idx == 3) break;
            }
        }
        return res;
    }
}

var maximumValueSum = function(board) {
    const m = board.length;
    const n = board[0].length;
    const rowTop3 = [];
    for (let r = 0; r < m; r++) {
        const row = [];
        for (let c = 0; c < n; c++) {
            row.push([board[r][c], c]);
        }
        row.sort((a, b) => b[0] - a[0]);
        rowTop3.push(row.slice(0, 3));
    }

    const mergeTop3 = (a, b) => {
        const combined = [...a, ...b];
        combined.sort((x, y) => y[0] - x[0]);
        const res = [];
        const seen = new Set();
        for (const [v, c] of combined) {
            if (!seen.has(c)) {
                seen.add(c);
                res.push([v, c]);
                if (res.length === 3) break;
            }
        }
        return res;
    };

    const pref = new Array(m);
    pref[0] = rowTop3[0];
    for (let r = 1; r < m; r++) {
        pref[r] = mergeTop3(pref[r - 1], rowTop3[r]);
    }

    const suff = new Array(m);
    suff[m - 1] = rowTop3[m - 1];
    for (let r = m - 2; r >= 0; r--) {
        suff[r] = mergeTop3(suff[r + 1], rowTop3[r]);
    }

    let maxSum = -Infinity;
    for (let r = 1; r < m - 1; r++) {
        for (const [v2, c2] of rowTop3[r]) {
            for (const [v1, c1] of pref[r - 1]) {
                if (c1 === c2) continue;
                for (const [v3, c3] of suff[r + 1]) {
                    if (c3 === c1 || c3 === c2) continue;
                    const sum = v1 + v2 + v3;
                    if (sum > maxSum) maxSum = sum;
                }
            }
        }
    }
    return maxSum;
};
